mapper.delete:
DELETE FROM PTL_RECE_POSITION_FLOW


      CDATE = #{cdate, jdbcType=DATE}


      AND TRADE_ID = #{tradeId}

mapper.select:
  select base.PAY_DATE from
  (
select
  PAY_DATE
  from PTL_RECE_POSITION_FLOW PTRFLOW
  where PTRFLOW.FINPROD_ID=#{finprodId,jdbcType=VARCHAR}
      and PTRFLOW.BRANCH=#{branch}
      and PTRFLOW.REC_TYPE='03'
      and PTRFLOW.HODING_TYPE ='03'
      and PTRFLOW.INPUT_TYPE='04'
     UNION ALL
  SELECT PAY_DATE
    FROM PTL_RECE_POSITION PTRFLOW
    WHERE PTRFLOW.FINPROD_ID=#{finprodId,jdbcType=VARCHAR}
    AND PTRFLOW.BRANCH      =#{branch}
    AND PTRFLOW.REC_TYPE    ='03'
    AND PTRFLOW.HODING_TYPE ='03'

      AND PTRFLOW.CDATE = #{cdate, jdbcType=DATE}


    AND PTRFLOW.PORTFOLIO_ID=#{portfolioId,jdbcType=VARCHAR}

  )base
  where rownum=1

mapper.update:
UPDATE PTL_RECE_POSITION SET AMOUNT = AMOUNT - #{amount}
WHERE PORTFOLIO_ID = #{portfolioId}
    AND SEC_ACCT_ID = #{secAcctId}
    AND FINPROD_ID = #{finprodId}
    AND BRANCH = #{branch}
    AND INV_AIM = #{invAim}
    AND HODING_TYPE = #{hodingType}
    AND CDATE = #{cdate}

UPDATE PTL_RECE_POSITION_FLOW
SET PAY_DATE = #{payDate}
WHERE FINPROD_ID = #{finprodId}
    AND BRANCH > #{vDate}
    AND BRANCH <= #{mDate}

mapper.select:
select TRADE_ID from WFL_TRD_PRODUCT_DEAL
