and ps in (#{PS25},#{PS26})

select nvl(amount,0) from PTL_RECE_POSITION_FLOW
where  BRANCH=#{branch}
and FINPROD_ID = #{finprodId}
and PORTFOLIO_ID=#{portfolioId}
and rec_type=#{REC_TYPE_03}
